import json
from typing import Any, Dict

def _parse(text):
    if not isinstance(text, str) or not text.strip():
        return {}
    t = text.strip()
    if ':' in t and not t.startswith('{') and not t.startswith('['):
        t = t.split(':', 1)[1].strip()
    try:
        v = json.loads(t)
        return v if isinstance(v, dict) else {'raw': t}
    except Exception:
        return {'raw': t}


def _req_summary(req, cfg):
    # requirement_summary：优先需求原文；否则从执行方案提取可读摘要（避免 JSON 大对象导致空串）
    req_plan = cfg.get('plan_json')
    if isinstance(req_plan, str):
        try:
            req_plan = json.loads(req_plan)
        except Exception:
            req_plan = None
    raw = req.get('raw') if isinstance(req, dict) else ''
    if isinstance(raw, str) and raw.strip():
        return raw[:500]
    parts = []
    if isinstance(req_plan, dict):
        base = req_plan.get('baseInfo') or {}
        prc = (req_plan.get('optionalInfo') or {}).get('printContent') or {}
        if base.get('prodPrcName'):
            parts.append(str(base['prodPrcName']))
        if prc.get('prcMonthFee'):
            parts.append('月费%s' % prc['prcMonthFee'])
        if prc.get('containResource'):
            parts.append('含%s' % prc['containResource'])
    if parts:
        return '；'.join(parts)[:500]
    return json.dumps(req_plan if isinstance(req_plan, dict) else req, ensure_ascii=False)[:500]

async def main(args):
    p = args.params
    cfg = _parse(p.get('config_result') or '')
    spec = _parse(p.get('spec_result') or '')
    fee = _parse(p.get('fee_result') or '')
    test = _parse(p.get('test_result') or '')
    req = _parse(p.get('requirement_result') or '')
    # 融合成员组合验证标记：plan 含 group/member_offers 时附加（审批看板动态渲染，避免脏占位符）
    plan_grp = cfg.get('plan_json')
    if isinstance(plan_grp, str):
        try:
            plan_grp = json.loads(plan_grp)
        except Exception:
            plan_grp = None
    has_members = bool(isinstance(plan_grp, dict) and (
        (isinstance(plan_grp.get('group'), dict) and plan_grp['group'].get('members'))
        or plan_grp.get('member_offers')))
    fusion_verification = '＋融合成员组合验证' if has_members else ''
    # config 环节：完整落地配置JSON（内含 offer_id 与 plan_json）
    offer_id = str(cfg.get('offer_id') or '')
    offer_name = str(cfg.get('offer_name') or '')
    # spec 环节：V2.5 起存储结构化 envelope（pass/error_list/audit_summary/audit_suggest），
    #   兼容旧版仅存 markdown 的情形（回退 raw 文本启发式判定）
    audit_summary = str(spec.get('audit_suggest') or spec.get('raw') or spec.get('audit_summary') or '')
    if str(spec.get('pass') or '') in ('0', '1'):
        spec_pass = str(spec.get('pass'))
    else:
        spec_pass = '1' if ('通过' in audit_summary and '驳回' not in audit_summary) else '0'
    # fee 环节：V2.5 起存储结构化 envelope（pass/risk_list/compare_list/risk_summary），
    #   兼容旧版仅存 markdown 的情形（回退 raw 文本启发式判定）
    risk_summary = str(fee.get('risk_summary') or fee.get('raw') or '')
    if str(fee.get('pass') or '') in ('0', '1'):
        fee_pass = str(fee.get('pass'))
    else:
        fee_pass = '0' if ('未通过' in risk_summary or '风险' in risk_summary.replace('未发现', '')) else '1'
    # test 环节：存储的是测试报告文本，受理凭证按标记提取
    test_report = str(test.get('raw') or test.get('test_report') or '')
    order_id = ''
    offer_inst_id = ''
    import re
    m = re.search(r'order[Ii]d[=：:]*\s*([A-Za-z0-9\-]+)', test_report)
    if m:
        order_id = m.group(1)
    m = re.search(r'offerInst[Ii]d[=：:]*\s*([A-Za-z0-9\-]+)', test_report)
    if m:
        offer_inst_id = m.group(1)
    test_passed = '1' if ('通过' in test_report and '失败' not in test_report.split('总体结论')[-1]) else '0'
    summary = {
        'offer_id': offer_id,
        'offer_name': offer_name,
        'fusion_verification': fusion_verification,
        'requirement_summary': _req_summary(req, cfg),
        'config': {'offer_id': offer_id,
                   'plan_json': cfg.get('plan_json')},
        'spec': {'pass': spec_pass, 'audit_summary': audit_summary},
        'fee': {'pass': fee_pass, 'risk_summary': risk_summary},
        'test': {'passed': test_passed, 'order_id': order_id,
                 'offer_inst_id': offer_inst_id, 'test_report': test_report},
        'all_pass': spec_pass == '1' and fee_pass == '1' and test_passed == '1',
    }
    ret: Output = {
        "summary_json": json.dumps(summary, ensure_ascii=False),
        "offer_id": offer_id,
        "fusion_verification": fusion_verification
    }
    return ret

import json, time, asyncio
import urllib.request, urllib.parse
from typing import Any, Dict

STATUS_URL = 'http://10.86.13.201:31281/api/v1/appstore/approval/status'
MAX_RETRY = 12
INTERVAL = 2

def _fetch(approval_id, offer_id):
    params = {}
    if approval_id:
        params['approval_id'] = approval_id
    if offer_id:
        params['offer_id'] = offer_id
    url = STATUS_URL + '?' + urllib.parse.urlencode(params)
    with urllib.request.urlopen(url, timeout=30) as resp:
        return json.loads(resp.read().decode('utf-8'))

def _norm_status(info):
    # 对齐后端口径：终态 通过/驳回；处理中 审批中/待审/待审核/进行中/approved
    st = str(info.get('status') or '').strip()
    if st in ('通过', '已通过'):
        return '通过'
    if st in ('驳回', '已驳回', '拒绝'):
        return '驳回'
    if str(info.get('approved') or '').lower() in ('true', 'yes', '1'):
        return '通过'
    if str(info.get('rejected') or '').lower() in ('true', 'yes', '1'):
        return '驳回'
    if st == '' or st in ('审批中', '待审', '待审核', '进行中', 'approved', 'pending', 'auditing'):
        return '审批中'
    return st


async def main(args):
    p = args.params
    approval_id = str(p.get('approval_id') or '')
    offer_id = str(p.get('offer_id') or '')
    out_status = '审批中'
    info = {}
    for i in range(MAX_RETRY):
        try:
            info = _fetch(approval_id, offer_id)
        except Exception:
            await asyncio.sleep(INTERVAL)
            continue
        out_status = _norm_status(info)
        if out_status in ('通过', '驳回'):
            break
        time.sleep(INTERVAL)
    ret: Output = {
        'status': out_status,
        'approval_id': str(info.get('approval_id') or approval_id),
        'approval_type': str(info.get('approval_type') or 'launch'),
        'current_node': str(info.get('current_node') or ''),
        'approver': str(info.get('approver') or ''),
        'opinion': str(info.get('opinion') or ''),
        'update_time': str(info.get('update_time') or ''),
        'approval_matrix': json.dumps(info.get('approval_matrix') or [], ensure_ascii=False),
    }
    return ret

import json, urllib.request
from typing import Any, Dict

DL_URL = 'http://10.86.13.201:31281/api/v1/appstore/script/download'

def _fetch(offer_id, approval_id):
    body = json.dumps({'offer_id': offer_id, 'approval_id': approval_id, 'kind': 'launch_script'}).encode('utf-8')
    req = urllib.request.Request(DL_URL, data=body, method='POST',
                                 headers={'Content-Type': 'application/json'})
    with urllib.request.urlopen(req, timeout=30) as resp:
        return json.loads(resp.read().decode('utf-8'))

async def main(args):
    p = args.params
    offer_id = str(p.get('offer_id') or '').strip()
    approval_id = str(p.get('approval_id') or '').strip()
    try:
        info = _fetch(offer_id, approval_id)
    except Exception:
        info = None
    if not info or not (info.get('download_url') or info.get('url')):
        ret: Output = {
            'backend_pending': '1',
            'download_url': '',
            'note': '配置/上线脚本下载端点暂不可达，可联系产商品中心获取加载脚本；后端就绪后可直接下载',
        }
    else:
        ret: Output = {
            'backend_pending': '0',
            'download_url': str(info.get('download_url') or info.get('url') or ''),
            'note': str(info.get('message') or '配置/上线脚本已生成，可点击链接下载'),
        }
    return ret

